--- a/src/model/todo.ts
+++ b/src/model/todo.ts
@@ -1,5 +1,10 @@
 export interface Todo {
   id: string;
   title: string;
   done: boolean;
+  dueDate?: string; // ISO date, e.g. 2026-10-31
 }
+
+export function isOverdue(todo: Todo, now = new Date()): boolean {
+  return !todo.done && !!todo.dueDate && new Date(todo.dueDate) < now;
+}

